# AKEF AST Lexical Parser
class ASTLexer:
    def parse_markdown(self, md_content: str) -> ASTNode:
        tokens = self.tokenize(md_content)
        root = ASTNode(type='DOCUMENT')
        for t in tokens:
            if t.type == 'HEADER':
                root.add_child(ASTNode(type='SLIDE_TITLE', value=t.text))
        return root

